import {Container} from "@/components/shared/Container/Container";
import Image from "next/image";
import {EnquiryLink} from "@/components/widgets/EnquiryLink/EnquiryLink";
import {homeImages} from "@/content/home";
import type {HomeContent} from "./types";
import styles from "./HomeCustomExtras.module.css";
import common from "./HomeCommon.module.css";

type HomeCustomExtrasBlockProps = {
    content: HomeContent["custom"];
    extrasContent: HomeContent["extras"];
    createLabel: string;
};

export function HomeCustomExtrasBlock({content, extrasContent, createLabel}: HomeCustomExtrasBlockProps) {
  const extras = [
    {id: "balloons", image: homeImages.balloons, label: extrasContent.balloons, alt: extrasContent.balloonAlt},
    {id: "card", image: homeImages.card, label: extrasContent.card, alt: extrasContent.cardAlt},
    {id: "chocolates", image: homeImages.chocolates, label: extrasContent.chocolates, alt: extrasContent.chocolateAlt}
  ];
  return (
    <Container as="section" className={styles.customAndExtras} aria-labelledby="home-custom-title">
      <div className={styles.custom}>
        <div className={`${common.editorial} ${styles.customCopy}`}>
          <p className={common.eyebrow}>{content.eyebrow}</p>
          <h2 id="home-custom-title" className={common.heading}>{content.title}</h2>
          <p className={`${common.body} ${styles.customBody}`}>{content.description}</p>
          <EnquiryLink variant="light">{createLabel}</EnquiryLink>
        </div>
        <div className={styles.customPhoto}>
          <Image src={homeImages.custom} alt={content.alt} fill sizes="(min-width: 1200px) 340px, (min-width: 600px) calc((100vw - 64px) / 2), calc(100vw - 40px)" className={common.cover} />
        </div>
      </div>
      <div className={styles.extras}>
        <h3>{extrasContent.title}</h3>
        <p className={common.body}>{extrasContent.description}</p>
        <div className={styles.extrasGrid}>
          {extras.map((extra) => (
            <figure key={extra.id} className={styles.extra}>
              <div className={`${styles.extraPhoto} ${extra.id === "balloons" ? styles.extraBalloonPhoto : ""}`}>
                <Image src={extra.image} alt={extra.alt} fill sizes="(min-width: 1200px) 146px, 152px" className={common.cover} />
              </div>
              <figcaption>{extra.label}</figcaption>
            </figure>
          ))}
        </div>
      </div>
    </Container>
  );
}
